<?php

namespace App\Support;

/**
 * Helpers for responsive images without a build step: WebP siblings
 * (photo.jpg -> photo.webp, generated by ImageOptimizer / images:webp).
 */
final class Images
{
    /** Browser URL: local files are relative to the current origin. */
    public static function url(?string $value): ?string
    {
        $value = trim((string) $value);
        if ($value === '') {
            return null;
        }

        if (preg_match('#^(?:data|blob):#i', $value)) {
            return $value;
        }

        $path = ltrim($value, '/');
        if (preg_match('#^(?:https?:)?//#i', $value)) {
            if (! self::isSiteHost(parse_url($value, PHP_URL_HOST))) {
                return $value;
            }

            $path = ltrim((string) parse_url($value, PHP_URL_PATH), '/');
            if (! preg_match('#^(?:public/)?(?:css|img|storage)/#', $path)) {
                return $value;
            }

            $suffix = strpbrk($value, '?#');
            $path .= $suffix === false ? '' : $suffix;
        }

        $path = preg_replace('#^public/(?=(?:css|img|storage)/)#', '', $path);

        return preg_match('#^(?:css|img|storage)/#', $path) ? '/'.$path : '/storage/'.$path;
    }

    /** Absolute image address for metadata and XML feeds. */
    public static function absoluteUrl(?string $value): ?string
    {
        $path = self::url($value);

        return $path !== null && str_starts_with($path, '/') && ! str_starts_with($path, '//')
            ? url($path)
            : $path;
    }

    public static function isSiteHost(?string $host): bool
    {
        $host = strtolower((string) $host);

        return $host !== '' && (
            $host === 'taketwostudio1603.com'
            || str_ends_with($host, '.taketwostudio1603.com')
            || $host === strtolower((string) parse_url((string) config('app.url'), PHP_URL_HOST))
            || $host === strtolower(request()->getHost())
        );
    }

    /** Rebase image sources saved by the blog editor without touching other links in the article. */
    public static function rebaseHtmlImages(string $html): string
    {
        return preg_replace_callback('~(<img\b[^>]*?\s+src\s*=\s*)(["\'])(.*?)\2~is', function (array $match): string {
            $source = html_entity_decode($match[3], ENT_QUOTES | ENT_HTML5, 'UTF-8');
            if (! preg_match('#^(?:https?:)?//#i', $source)) {
                return $match[0];
            }

            $url = self::url($source);

            return $url === $source ? $match[0] : $match[1].$match[2].e($url).$match[2];
        }, $html) ?? $html;
    }

    /** Absolute filesystem path for a same-origin asset URL or a relative public path; null for foreign URLs. */
    public static function localPath(?string $url): ?string
    {
        if (! $url) {
            return null;
        }

        $path = $url;

        if (preg_match('#^(?:https?:)?//#i', $url)) {
            if (! self::isSiteHost(parse_url($url, PHP_URL_HOST))) {
                return null;
            }

            $path = (string) parse_url($url, PHP_URL_PATH);
        }

        $path = rawurldecode(ltrim(strtok($path, '?#') ?: '', '/'));

        if ($path === '' || str_contains($path, '..')) {
            return null;
        }

        $full = public_path($path);

        return is_file($full) ? $full : null;
    }

    /** URL of the WebP sibling when it exists, otherwise null. */
    public static function webpUrl(?string $url): ?string
    {
        $local = self::localPath($url);

        if (! $local || ! preg_match('/\.(jpe?g|png)$/i', $local)) {
            return null;
        }

        $webp = preg_replace('/\.(jpe?g|png)$/i', '.webp', $local);

        if (! is_file($webp)) {
            return null;
        }

        return preg_replace('/\.(jpe?g|png)([?#].*)?$/i', '.webp$2', $url);
    }


    /**
     * Write photo.webp next to photo.jpg/png (skipped when up to date).
     * Returns the webp path or null when the source cannot be converted.
     */
    public static function makeWebp(string $fullPath, int $quality = 80): ?string
    {
        if (! is_file($fullPath) || ! preg_match('/\.(jpe?g|png)$/i', $fullPath) || ! function_exists('imagewebp')) {
            return null;
        }

        $webp = preg_replace('/\.(jpe?g|png)$/i', '.webp', $fullPath);

        if (is_file($webp) && filemtime($webp) >= filemtime($fullPath)) {
            return $webp;
        }

        $info = @getimagesize($fullPath);
        if (! $info) {
            return null;
        }

        $image = match ($info[2]) {
            IMAGETYPE_JPEG => @imagecreatefromjpeg($fullPath),
            IMAGETYPE_PNG => @imagecreatefrompng($fullPath),
            default => null,
        };

        if (! $image) {
            return null;
        }

        if ($info[2] === IMAGETYPE_PNG) {
            imagepalettetotruecolor($image);
            imagealphablending($image, true);
            imagesavealpha($image, true);
        }

        $ok = imagewebp($image, $webp, $quality);
        imagedestroy($image);

        return $ok ? $webp : null;
    }
}
